<div class="preview-container @ThemeClass @FontClass @(Settings.CompactMode ? "compact" : "")">
    <div class="preview-header">
        <strong>Preview</strong>
    </div>
    <div class="preview-body">
        <h6>Sample Heading</h6>
        <p>This is how your content will look with the selected settings.</p>
        <div class="d-flex gap-2 mb-2">
            <span class="badge bg-primary">Tag One</span>
            <span class="badge bg-secondary">Tag Two</span>
        </div>
        <button class="btn btn-primary btn-sm">Sample Button</button>
    </div>
    <div class="preview-footer text-muted">
        Language: @Settings.Language
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;

    private string ThemeClass => Settings.Theme switch
    {
        "Dark" => "preview-dark",
        "Light" => "preview-light",
        _ => "preview-system"
    };

    private string FontClass => Settings.FontSize switch
    {
        "Small" => "font-small",
        "Large" => "font-large",
        _ => "font-medium"
    };
}
"}

