.preview-container {
    border: 1px solid #dee2e6;
    border-radius: 8px;
    overflow: hidden;
    transition: all 0.2s ease;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-body {
    padding: 1rem;
}

.preview-footer {
    padding: 0.5rem 1rem;
    border-top: 1px solid #dee2e6;
    font-size: 0.85rem;
}

/* Theme variants */
.preview-light, .preview-system {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-dark .preview-header,
.preview-dark .preview-footer {
    border-color: #444;
}

/* Font sizes */
.font-small { font-size: 0.85rem; }
.font-medium { font-size: 1rem; }
.font-large { font-size: 1.15rem; }

/* Compact mode */
.compact .preview-header,
.compact .preview-footer {
    padding: 0.35rem 0.75rem;
}

.compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.compact .preview-body p {
    margin-bottom: 0.25rem;
}

