<h5>Profile</h5>
<hr />

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert @(isError ? "alert-danger" : "alert-success") py-2 d-flex justify-content-between align-items-center">
        @statusMessage
        <button type="button" class="btn-close btn-close-sm" @onclick="() => statusMessage = null"></button>
    </div>
}

<div class="row mb-3">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="editName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="editEmail" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="editBio"></textarea>
        </div>
    </div>
    <div class="col-md-4">
        <label class="form-label">Avatar</label>
        <div class="avatar-preview mb-2">
            @if (!string.IsNullOrWhiteSpace(Profile.AvatarUrl))
            {
                <img src="@Profile.AvatarUrl" alt="Avatar" class="img-fluid rounded-circle" style="max-width:120px;max-height:120px;" />
            }
            else
            {
                <div class="avatar-placeholder rounded-circle d-flex align-items-center justify-content-center"
                     style="width:120px;height:120px;background:#dee2e6;font-size:2rem;color:#6c757d;">
                    @(string.IsNullOrEmpty(Profile.DisplayName) ? "?" : Profile.DisplayName[0])
                </div>
            }
        </div>
        <small class="text-muted text-break">@Profile.AvatarUrl</small>
    </div>
</div>

<div class="d-flex gap-2">
    <button class="btn btn-primary" @onclick="HandleSave" disabled="@isSaving">
        @(isSaving ? "Saving…" : "Save Changes")
    </button>
    <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
        Discard Changes
    </button>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string editName = "";
    private string editEmail = "";
    private string editBio = "";
    private bool isSaving;
    private string? statusMessage;
    private bool isError;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        editName = Profile.DisplayName;
        editEmail = Profile.Email;
        editBio = Profile.Bio;
    }

    private void DiscardChanges()
    {
        ResetFields();
        statusMessage = null;
    }

    private async Task HandleSave()
    {
        isSaving = true;
        isError = false;
        statusMessage = null;

        try
        {
            var updated = Profile with
            {
                DisplayName = editName,
                Email = editEmail,
                Bio = editBio
            };
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully.";
        }
        catch (Exception ex)
        {
            statusMessage = ex.Message;
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}
