<h5>Notifications</h5>
<hr />

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-success py-2">@statusMessage</div>
}

<div class="mb-4">
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="emailNotif"
               checked="@editEmailNotif" @onchange="e => editEmailNotif = (bool)e.Value!" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="pushNotif"
               checked="@editPushNotif" @onchange="e => editPushNotif = (bool)e.Value!" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>
    <div class="form-check form-switch mb-2">
        <input class="form-check-input" type="checkbox" id="weeklyDigest"
               checked="@editWeeklyDigest" @onchange="e => editWeeklyDigest = (bool)e.Value!" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

@if (editMutedChannels.Count > 0)
{
    <h6>Muted Channels</h6>
    <div class="mb-3">
        @foreach (var channel in allChannels)
        {
            var ch = channel;
            <div class="form-check mb-1">
                <input class="form-check-input" type="checkbox" id="@($"ch-{ch}")"
                       checked="@editMutedChannels.Contains(ch)"
                       @onchange="e => ToggleChannel(ch, (bool)e.Value!)" />
                <label class="form-check-label" for="@($"ch-{ch}")">@ch</label>
            </div>
        }
    </div>
}

<button class="btn btn-primary" @onclick="HandleSave" disabled="@isSaving">
    @(isSaving ? "Saving…" : "Save Preferences")
</button>

@code {
    [Parameter, EditorRequired] public NotificationPrefs Prefs { get; set; } = default!;
    [Parameter] public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool editEmailNotif;
    private bool editPushNotif;
    private bool editWeeklyDigest;
    private HashSet<string> editMutedChannels = [];
    private List<string> allChannels = [];
    private bool isSaving;
    private string? statusMessage;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            editEmailNotif = Prefs.EmailNotifications;
            editPushNotif = Prefs.PushNotifications;
            editWeeklyDigest = Prefs.WeeklyDigest;
            allChannels = Prefs.MutedChannels.ToList();
            editMutedChannels = [.. Prefs.MutedChannels];
        }
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            editMutedChannels.Add(channel);
        else
            editMutedChannels.Remove(channel);
    }

    private async Task HandleSave()
    {
        isSaving = true;
        statusMessage = null;

        try
        {
            var updated = new NotificationPrefs(
                editEmailNotif,
                editPushNotif,
                editWeeklyDigest,
                editMutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            statusMessage = "Preferences saved successfully.";
        }
        finally
        {
            isSaving = false;
        }
    }
}
