{"file_text": "
<h5>Appearance</h5>
<hr />

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-success py-2">@statusMessage</div>
}

<div class="row">
    <div class="col-md-6">
        <div class="mb-3">
            <label class="form-label fw-semibold">Theme</label>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                var t = theme;
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                           checked="@(editTheme == t)"
                           @onchange="() => editTheme = t" />
                    <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                </div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold">Font Size</label>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                var s = size;
                <div class="form-check">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"font-{s}")"
                           checked="@(editFontSize == s)"
                           @onchange="() => editFontSize = s" />
                    <label class="form-check-label" for="@($"font-{s}")">@s</label>
                </div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label fw-semibold" for="language-select">Language</label>
            <select class="form-select" id="language-select" @bind="editLanguage">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
                <option value="Chinese">Chinese</option>
            </select>
        </div>

        <div class="mb-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode"
                       checked="@editCompactMode"
                       @onchange="e => editCompactMode = (bool)e.Value!" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="HandleSave" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save")
        </button>
    </div>

    <div class="col-md-6">
        <AppearancePreview Settings="@CurrentPreview" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Appearance { get; set; } = default!;
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string editTheme = "System";
    private string editFontSize = "Medium";
    private string editLanguage = "English";
    private bool editCompactMode;
    private bool isSaving;
    private string? statusMessage;

    private AppearanceSettings CurrentPreview =>
        new(editTheme, editFontSize, editLanguage, editCompactMode);

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            editTheme = Appearance.Theme;
            editFontSize = Appearance.FontSize;
            editLanguage = Appearance.Language;
            editCompactMode = Appearance.CompactMode;
        }
    }

    private async Task HandleSave()
    {
        isSaving = true;
        statusMessage = null;

        try
        {
            await OnSave.InvokeAsync(CurrentPreview);
            statusMessage = "Appearance saved successfully.";
        }
        finally
        {
            isSaving = false;
        }
    }
}
", "path": "/tmp/sv-441a6015a9a840bcb66447d382271353/Components/Pages/Settings/AppearanceSection.razor"}

